import{_ as a,o as i,c as r,a0 as s}from"./chunks/framework.BgLNGgvZ.js";const u=JSON.parse('{"title":"Cloudflare::API::Hyperdrive","description":"","frontmatter":{},"headers":[],"relativePath":"lib/Cloudflare/API/Hyperdrive.pm.md","filePath":"lib/Cloudflare/API/Hyperdrive.pm.md"}'),o={name:"lib/Cloudflare/API/Hyperdrive.pm.md"};function t(n,e,d,l,p,c){return i(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="cloudflare-api-hyperdrive" tabindex="-1">Cloudflare::API::Hyperdrive <a class="header-anchor" href="#cloudflare-api-hyperdrive" aria-label="Permalink to &quot;Cloudflare::API::Hyperdrive&quot;">​</a></h1><h1 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h1><p>Cloudflare::API::Hyperdrive - manage Hyperdrive connection configurations</p><h1 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h1><div class="language-perl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">perl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">my</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $configs=$api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hyperdrive()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list_configs();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">my</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $config=$api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hyperdrive()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">get_config($config_id);</span></span></code></pre></div><h1 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h1><p>These account-scoped REST methods manage Hyperdrive configurations for external PostgreSQL or MySQL databases. They do not run SQL. Applications query through a Worker Hyperdrive binding and a database driver. Cloudflare&#39;s origin password is write-only; keep request bodies and credentials out of logs and source control.</p><h1 id="methods" tabindex="-1">METHODS <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;METHODS&quot;">​</a></h1><ul><li><strong>list_configs(%query)</strong> — List configurations. Named filters become query parameters. Returns <code>result</code>; <code>full_response =&gt; 1</code> retains pagination information.</li><li><strong>get_config($id, %options)</strong> — Retrieve a configuration by ID and return its <code>result</code>.</li><li><strong>create_config(%body, %options)</strong> — POST a Cloudflare configuration body and return its <code>result</code>.</li><li><strong>replace_config($id, %body, %options)</strong> — PUT a replacement configuration and return its <code>result</code>.</li><li><strong>update_config($id, %body, %options)</strong> — PATCH a configuration and return its <code>result</code>.</li><li><strong>delete_config($id, %options)</strong> — DELETE a configuration and return the endpoint&#39;s <code>result</code>, possibly <code>undef</code> for an empty body.</li></ul><p>Every JSON method accepts <code>full_response =&gt; 1</code> for the complete decoded envelope. IDs are percent-encoded. Write bodies must be hash references; Cloudflare defines the accepted fields.</p><h1 id="errors" tabindex="-1">ERRORS <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;ERRORS&quot;">​</a></h1><p>Missing account context, invalid bodies or IDs, HTTP and transport failures, and Cloudflare envelope failures cause exceptions as described in <code>Cloudflare::API</code>.</p><h1 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h1><p><a href="./../API.pm.html">Cloudflare::API</a></p><h1 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h1><p>Andrew Speer <a href="mailto:andrew.speer@isolutions.com.au" target="_blank" rel="noreferrer">andrew.speer@isolutions.com.au</a></p><h1 id="license-and-copyright" tabindex="-1">LICENSE and COPYRIGHT <a class="header-anchor" href="#license-and-copyright" aria-label="Permalink to &quot;LICENSE and COPYRIGHT&quot;">​</a></h1><p>Copyright (c) 2026 Andrew Speer. This software is free software under the same terms as Perl 5.</p>`,18)])])}const f=a(o,[["render",t]]);export{u as __pageData,f as default};
